def build_roadmap(a):
    blocked=bool(a.gates)
    return [dict(phase='Business and data validation',weeks='1–2',objective='Confirm a defensible decision and dataset.',
        activities=a.gates or ['Confirm target, prediction timing, data depth, access, privacy and baseline.'],owner=a.challenge.owner or 'Business sponsor to identify',
        deliverable='Signed decision definition and data inventory',dependencies='Business and data owner availability',exit='All hard gates resolved; evidence verified'),
      dict(phase='Technical evaluation',weeks='3–5 (conditional)',objective='Compare baselines on a point-in-time evaluation.',
        activities=(['Collect or reconstruct outcomes before any benchmark; extend this phase if needed.'] if blocked else [])+['Prepare authorized dataset; chronological holdout and entity grouping where appropriate.',f"Establish baseline: {a.use_case['baseline']}.",'Evaluate TabPFN only where authorized and available; compare operational constraints.'],owner='Data science lead + data owner',deliverable='Leakage-reviewed benchmark and error analysis',dependencies='Phase 1 exit criteria; model access; sufficient outcomes',exit='Reproducible baseline comparison; metric thresholds agreed'),
      dict(phase='Business validation',weeks='6–8 (conditional)',objective='Test operational usefulness and benefit assumptions.',activities=[f"Review {a.use_case['action']}",'Agree alert capacity, intervention costs and scenario assumptions; review errors with stakeholders.'],owner=a.challenge.owner or 'Business owner to identify',deliverable='Business tradeoff review and revised scenarios',dependencies='Valid technical evaluation and stakeholder participation',exit='Operational thresholds and costs documented; no savings assumed validated'),
      dict(phase='Adoption decision',weeks='9–12 (conditional)',objective='Make an evidence-based go/no-go decision.',activities=['Assess incremental value, integration costs, security, governance and monitored rollout.','Defer or stop when incumbent performance or data limitations invalidate the hypothesis.'],owner='Executive sponsor + IT / security',deliverable='Go/no-go memo and conditional rollout plan',dependencies='Business validation; governance approval',exit='Accountable decision, monitoring plan and ownership confirmed')]
